-- mod-temucraft-merchants: Craftsman's Writs and the supply factions (Azeroth Commerce Authority 2233, Durotar Supply and
-- Logistics 2234). Writs 601710+ start daily quests: bring the crafted item to the faction's quartermaster for
-- reputation, Merchant's Favor (601700) and money. Re-runnable.
SET @Favor := 601700;
SET @Writ := 601710;
SET @CampSpawn := 9200160;
SET @Camp := 601971;
DELETE FROM `item_template` WHERE `entry` = @Favor OR `entry` BETWEEN @Writ AND @Writ+259;
DELETE FROM `quest_template` WHERE `ID` BETWEEN @Writ AND @Writ+259;
DELETE FROM `creature_questender` WHERE `quest` BETWEEN @Writ AND @Writ+259;

DELETE FROM `creature` WHERE `guid` BETWEEN @CampSpawn AND @CampSpawn+3;
DELETE FROM `creature_template` WHERE `entry` BETWEEN @Camp AND @Camp+3;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN @Camp AND @Camp+3;
DELETE FROM `npc_vendor` WHERE `entry` IN (@Camp+1, @Camp+3);
-- Looks borrowed from existing traders: human vendors for the Authority, a goblin and an orc for the Horde
